      "statusIndicacao": "REPROVADO PELO ÓRGÃO",
      "statusFinanceiro": "Reprovado",
      "estagioAtual": "reprovada",
      "aprovado": "Não",
      "justificativaReprovacao": "Em conformidade, com as informações prestadas pela área técnica da SEE (Superintendência de Aquisições, Patrimônio e Alimentação Escolar), prestamos os esclarecimentos que se seguem: _x000D_ Levando-se em conta a dificuldade encontrada por esta Secretaria para a aquisição do veículo de 7 lugares, objeto da Indicação nº 60410, tendo em vista as empresas solicitarem um prazo superior há 150 dias para a entrega do bem; as tentativas frustradas de realizar dois pregões que foram desertos; assim como buscar atas vigentes, porém com adesões negadas, registra-se o impedimento de ordem técnica na referida indicação, considerando a impossibilidade de execução orçamentária e financeira no exercício de 2021. _x000D_ Cabe ressaltar que referente à adesão como não participante a ata de registro de preços para aquisição, a SEE tentou aderir a diversas atas, todavia não logrou êxito, pois devido à indisponibilidade de quantitativos para carona e principalmente preço, as adesões foram negadas.",
